import React, { useEffect, useRef } from 'react';
import { PROJECTS } from '../constants';
import { SectionId, Project } from '../types';

const ProjectCard = ({ project }: { project: Project }) => {
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      if (wrapperRef.current) {
        const parent = wrapperRef.current.parentElement;
        if (parent) {
          const rect = parent.getBoundingClientRect();
          const windowHeight = window.innerHeight;

          // Check if element is in view
          if (rect.top < windowHeight && rect.bottom > 0) {
            // Calculate percentage of position in viewport (0 to 1)
            // 0 when top enters bottom of screen
            // 1 when bottom leaves top of screen
            // actually we want a simple parallax relative to center?
            // Let's do a simple translateY based on scroll position relative to viewport

            const speed = 0.1;
            const yOffset = (windowHeight - rect.top) * speed - (windowHeight * speed * 0.5);

            // Limit the transform to avoid white space if scrolled too fast/far, 
            // though the wrapper height 120% should handle typical viewports.
            wrapperRef.current.style.transform = `translateY(${yOffset}px)`;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial calculation
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="group bg-white rounded-2xl overflow-hidden border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300">
      <div className="relative aspect-[4/3] overflow-hidden bg-slate-200">
        {/* Parallax Wrapper - Taller than container */}
        <div 
          ref={wrapperRef} 
          className="absolute inset-0 h-[120%] -top-[10%] w-full will-change-transform"
        >
          <img 
            src={project.imageUrl} 
            alt={project.title} 
            loading="lazy"
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
          />
        </div>

        {/* Overlay */}
        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center z-10">
          <span className="bg-white text-slate-900 px-6 py-2 rounded-full font-medium text-sm transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
            View Case Study
          </span>
        </div>
      </div>
      <div className="p-6 relative z-20 bg-white">
        <p className="text-xs font-bold text-blue-600 uppercase tracking-wider mb-2">{project.category}</p>
        <h4 className="text-xl font-bold text-slate-900 mb-2">{project.title}</h4>
        <p className="text-slate-600 text-sm">{project.description}</p>
      </div>
    </div>
  );
};

