  useEffect(() => {
    // Parallax Effect
    const handleScroll = () => {
      const scrolled = window.scrollY;
      if (blob1Ref.current) {
        blob1Ref.current.style.transform = `translateY(${scrolled * 0.3}px) rotate(${scrolled * 0.05}deg)`;
