        </div>
      </div>
    </div>
  );
};

// --- Project Card Component ---
const ProjectCard = ({ project, onClick }: { project: Project; onClick: () => void }) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const [shouldLoadVideo, setShouldLoadVideo] = useState(false);

  useEffect(() => {
    // Parallax Effect
    const handleScroll = () => {
      if (wrapperRef.current) {
        const parent = wrapperRef.current.parentElement;
        if (parent) {
          const rect = parent.getBoundingClientRect();
          const windowHeight = window.innerHeight;

          if (rect.top < windowHeight && rect.bottom > 0) {
            const speed = 0.1;
            const yOffset = (windowHeight - rect.top) * speed - (windowHeight * speed * 0.5);
            wrapperRef.current.style.transform = `translateY(${yOffset}px)`;
          }
        }
      }
    };

    // Visibility Observer for Entrance Animation
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1, rootMargin: "0px 0px -50px 0px" }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    window.addEventListener('scroll', handleScroll);
    handleScroll(); 
    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (cardRef.current) observer.unobserve(cardRef.current);
    };
  }, []);

  const handleMouseEnter = () => {
    setIsHovered(true);
    // Lazy load: only set video source to load when user hovers
    if (project.demoVideoUrl) {
      setShouldLoadVideo(true);
      // Small delay to ensure ref is populated if it was just rendered
      setTimeout(() => {
        if (videoRef.current) {
            videoRef.current.currentTime = 0;
            const playPromise = videoRef.current.play();
            if (playPromise !== undefined) {
                playPromise.catch(error => {
                    console.debug("Video autoplay prevented:", error);
                });
            }
        }
      }, 0);
    }
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    if (project.demoVideoUrl && videoRef.current) {
        videoRef.current.pause();
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsMuted(prev => !prev);
  };

  return (
    <div 
      ref={cardRef}
      className={`group bg-white rounded-2xl overflow-hidden border border-slate-100 shadow-sm hover:shadow-2xl transition-all duration-700 ease-out transform ${
        isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
      }`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-slate-200">
        <div 
          ref={wrapperRef} 
          className="absolute inset-0 h-[120%] -top-[10%] w-full will-change-transform"
        >
          <img 
            src={project.imageUrl} 
            alt={project.title} 
            loading="lazy"
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
          />
        </div>

        {/* Video Preview on Hover (Lazy Loaded) */}
        {project.demoVideoUrl && shouldLoadVideo && (
            <video
                ref={videoRef}
                src={project.demoVideoUrl}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 pointer-events-none ${isHovered ? 'opacity-100' : 'opacity-0'}`}
                muted={isMuted}
                loop
                playsInline
                preload="metadata"
            />
        )}

        {/* Mute Toggle Button - Visible when video is playing */}
        {project.demoVideoUrl && shouldLoadVideo && isHovered && (
            <button 
                onClick={toggleMute}
                className="absolute top-4 right-4 z-20 p-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white transition-all duration-200 hover:scale-110"
                aria-label={isMuted ? "Unmute preview" : "Mute preview"}
                title={isMuted ? "Unmute" : "Mute"}
            >
                {isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>
        )}

        {/* Hover Overlay */}
        <div 
          className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center z-10 cursor-pointer backdrop-blur-[2px] ${
            project.demoVideoUrl && isHovered ? 'bg-slate-900/40' : 'bg-slate-900/70'
          }`} 
          onClick={onClick}
        >
          {/* Wrapper for entrance transition to avoid conflict with pulse animation */}
          <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-75 flex flex-col items-center gap-3">
            <button className="bg-white text-slate-900 px-6 py-3 rounded-full font-bold text-sm shadow-xl hover:bg-brand-purple hover:text-white flex items-center gap-2 group/btn transition-colors animate-subtle-pulse">
              View Case Study 
              <ArrowUpRight size={18} className="group-hover/btn:translate-x-0.5 group-hover/btn:-translate-y-0.5 transition-transform" />
            </button>

            {project.demoVideoUrl && (
               <span className="inline-flex items-center gap-1 text-white text-xs font-medium bg-black/50 px-3 py-1 rounded-full backdrop-blur-sm">
                 <Film size={12} />
                 {isHovered ? 'Playing Preview' : 'Video Demo Available'}
               </span>
            )}
          </div>
        </div>
      </div>
      <div className="p-6 relative z-20 bg-white">
        <div className="flex items-start justify-between mb-3">
           <span className="px-2 py-1 bg-brand-blue/10 text-brand-blue rounded text-[10px] font-bold uppercase tracking-wider">{project.category}</span>
           {/* Tags Preview */}
           <div className="flex gap-1">
             {project.technologies?.slice(0, 2).map(t => (
               <span key={t} className="w-2 h-2 rounded-full bg-slate-200" title={t}></span>
             ))}
           </div>
        </div>
        <h4 className="text-xl font-bold text-slate-900 mb-2 group-hover:text-brand-purple transition-colors">{project.title}</h4>
        <p className="text-slate-600 text-sm line-clamp-2">{project.description}</p>
      </div>
    </div>
  );
};

