  const { pathname } = useLocation();

  useEffect(() => {
    // Small timeout ensures DOM is ready before scrolling
    const timer = setTimeout(() => {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    }, 0);

    return () => clearTimeout(timer);
  }, [pathname]);

  return null;
};

