                onClick={() => handleNavClick(item.href)}
              >
                {item.label}
              </Link>
            ))}
            <Button 
              className="w-full mt-4" 
              onClick={() => {
                setIsMobileMenuOpen(false);
                navigate('/contact');
              }}
            >
              Get Started
            </Button>
          </nav>
        </div>
      )}
    </header>
  );
