// --- Project Card Component ---
interface ProjectCardProps {
  project: Project;
  onClick: () => void;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onClick }) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const [shouldLoadVideo, setShouldLoadVideo] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (cardRef.current) observer.observe(cardRef.current);
    return () => { if (cardRef.current) observer.unobserve(cardRef.current); };
  }, []);

  const handleMouseEnter = () => {
    setIsHovered(true);
    if (project.demoVideoUrl) {
      setShouldLoadVideo(true);
      setTimeout(() => {
        if (videoRef.current) {
            videoRef.current.currentTime = 0;
            videoRef.current.play().catch(() => {});
        }
      }, 0);
    }
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    if (project.demoVideoUrl && videoRef.current) videoRef.current.pause();
  };

  return (
    <div 
      ref={cardRef}
      className={`group bg-white dark:bg-slate-900 rounded-2xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm hover:shadow-2xl dark:hover:shadow-blue-900/10 transition-all duration-700 ease-out transform ${
        isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
      }`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-slate-200 dark:bg-slate-800">
        <div ref={wrapperRef} className="absolute inset-0 h-[120%] -top-[10%] w-full will-change-transform">
          <img src={project.imageUrl} alt={project.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"/>
        </div>

        {project.demoVideoUrl && shouldLoadVideo && (
            <video
                ref={videoRef}
                src={project.demoVideoUrl}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 pointer-events-none ${isHovered ? 'opacity-100' : 'opacity-0'}`}
                muted={isMuted}
                loop
                playsInline
            />
        )}

        {project.demoVideoUrl && shouldLoadVideo && isHovered && (
            <button 
                onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
                className="absolute top-4 right-4 z-20 p-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white transition-all hover:scale-110"
            >
                {isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>
        )}

        <div className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center z-10 cursor-pointer backdrop-blur-[2px] ${project.demoVideoUrl && isHovered ? 'bg-slate-900/40' : 'bg-slate-900/70'}`} onClick={onClick}>
          <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-75 flex flex-col items-center gap-3">
            <button className="bg-white text-slate-900 px-6 py-3 rounded-full font-bold text-sm shadow-xl hover:bg-brand-purple hover:text-white flex items-center gap-2 group/btn transition-colors animate-subtle-pulse">
              View Case Study <ArrowUpRight size={18} />
            </button>
          </div>
        </div>
      </div>
      <div className="p-6 relative z-20 bg-white dark:bg-slate-900">
        <div className="flex items-start justify-between mb-3">
           <span className="px-2 py-1 bg-brand-blue/10 dark:bg-brand-blue/20 text-brand-blue dark:text-brand-blue rounded text-[10px] font-bold uppercase tracking-wider">{project.category}</span>
        </div>
        <h4 className="text-xl font-bold text-slate-900 dark:text-white mb-2 group-hover:text-brand-purple transition-colors">{project.title}</h4>
        <p className="text-slate-600 dark:text-slate-400 text-sm line-clamp-2">{project.description}</p>
      </div>
    </div>
  );
};

// --- Main Portfolio Component ---
export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(ALL_TAG);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [visibleCount, setVisibleCount] = useState(6);
  const location = useLocation();
  const isPage = location.pathname === '/portfolio';
  const HeadingTag = isPage ? 'h1' : 'h3';

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const allTags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];

  const getCategoryCount = (cat: string) => cat === ALL_CATEGORY ? PROJECTS.length : PROJECTS.filter(p => p.category === cat).length;
  const getTagCount = (tag: string) => tag === ALL_TAG ? PROJECTS.length : PROJECTS.filter(p => p.technologies && p.technologies.includes(tag)).length;

  const filteredProjects = PROJECTS.filter(p => {
    return (activeCategory === ALL_CATEGORY || p.category === activeCategory) && 
           (activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag)));
  });

  const displayedProjects = filteredProjects.slice(0, visibleCount);

  return (
    <section id={SectionId.PORTFOLIO} className="py-24 pt-32 bg-slate-50 dark:bg-slate-950 min-h-screen">
      <div className="container mx-auto px-6">
        <div className="text-center max-w-3xl mx-auto mb-12">
          <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">{isPage ? 'Portfolio' : 'Featured Work'}</h2>
          <HeadingTag className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white leading-tight mb-4">
            Showcasing our success stories.
          </HeadingTag>
          <p className="text-slate-600 dark:text-slate-400 text-lg">
            From concept to launch, we've helped businesses across the globe achieve their digital goals.
          </p>
        </div>

        {/* Category Filters */}
        <div className="flex flex-wrap justify-center gap-3 mb-8">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => { setActiveCategory(cat); setVisibleCount(6); }}
              className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 transform ${
                activeCategory === cat
                  ? 'bg-brand-blue text-white shadow-lg scale-105 ring-2 ring-brand-blue ring-offset-2 ring-offset-slate-50 dark:ring-offset-slate-900'
                  : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 hover:scale-105'
              }`}
            >
              {cat} <span className={`ml-2 text-xs font-bold ${activeCategory === cat ? 'text-slate-200' : 'text-slate-500'}`}>{getCategoryCount(cat)}</span>
            </button>
          ))}
        </div>

        {/* Tag Filters */}
        <div className="flex items-center justify-center gap-2 mb-12 overflow-x-auto no-scrollbar py-2 px-4 max-w-5xl mx-auto">
          <div className="flex items-center gap-2 bg-white/50 dark:bg-slate-900/50 p-2 rounded-full border border-slate-200 dark:border-slate-800 backdrop-blur-sm">
             <Tag size={16} className="text-slate-400 ml-2" />
             {allTags.map((tag) => (
              <button
                key={tag}
                onClick={() => { setActiveTag(tag); setVisibleCount(6); }}
                className={`px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 whitespace-nowrap flex items-center gap-1 ${
                  activeTag === tag
                    ? 'bg-slate-800 dark:bg-slate-700 text-white shadow-md'
                    : 'bg-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-800'
                }`}
              >
                {tag} <span className="text-[10px] opacity-70">{getTagCount(tag)}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 min-h-[400px]">
          {displayedProjects.map((project) => (
            <ProjectCard key={project.id} project={project} onClick={() => setSelectedProject(project)} />
          ))}
          {displayedProjects.length === 0 && (
            <div className="col-span-full flex flex-col items-center justify-center text-slate-400 py-12">
               <div className="w-16 h-16 bg-slate-100 dark:bg-slate-900 rounded-full flex items-center justify-center mb-4"><Code2 className="w-8 h-8 text-slate-300" /></div>
               <p className="font-medium">No projects found.</p>
               <button onClick={() => { setActiveCategory(ALL_CATEGORY); setActiveTag(ALL_TAG); }} className="mt-4 text-brand-blue text-sm hover:underline">Clear all filters</button>
            </div>
          )}
        </div>

        {visibleCount < filteredProjects.length && (
          <div className="mt-16 text-center">
            <Button variant="outline" onClick={() => setVisibleCount(p => p + 3)} className="group px-8 dark:text-slate-300 dark:border-slate-700 dark:hover:bg-slate-800">
              View More Projects <ArrowDown className="ml-2 w-4 h-4 transition-transform group-hover:translate-y-1" />
            </Button>
          </div>
        )}
      </div>

      <ProjectModal project={selectedProject} onClose={() => setSelectedProject(null)} onProjectSelect={setSelectedProject} />
    </section>
  );
};

