import { COMPANY_NAME, NAV_ITEMS } from '../constants';
import { Tooltip } from './ui/Tooltip';

export const Footer: React.FC = () => {
  const [email, setEmail] = useState('');
  const [subscribeStatus, setSubscribeStatus] = useState<'idle' | 'loading' | 'success'>('idle');
  const [isVisible, setIsVisible] = useState(false);
  const footerRef = useRef<HTMLElement>(null);
  const location = useLocation();

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (footerRef.current) observer.observe(footerRef.current);
    return () => { if (footerRef.current) observer.disconnect(); };
  }, []);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || subscribeStatus === 'loading') return;
    setSubscribeStatus('loading');
    setTimeout(() => {
      setSubscribeStatus('success');
      setEmail('');
      setTimeout(() => setSubscribeStatus('idle'), 5000);
    }, 1500);
  };

  const handleNavClick = (path: string) => {
    if (location.pathname === path) window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const getFadeInClass = (delayIndex: number) => {
    return `transition-all duration-700 ease-out transform ${
      isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
    }`;
  };

  const styleDelay = (index: number) => ({ transitionDelay: `${index * 150}ms` });

  return (
    <footer 
      ref={footerRef}
      className="bg-slate-950 text-slate-400 py-16 border-t border-slate-800 mt-auto"
    >
      <div className="container mx-auto px-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 mb-12">

          <div className={`space-y-6 ${getFadeInClass(0)}`} style={styleDelay(0)}>
            <Link to="/" onClick={() => handleNavClick('/')} className="flex items-center gap-2 text-white group">
              <div className="w-8 h-8 bg-brand-blue rounded-lg flex items-center justify-center transition-transform group-hover:scale-110 duration-300">
                <Terminal size={16} className="text-white" />
              </div>
              <span className="text-xl font-bold">{COMPANY_NAME}</span>
            </Link>
            <p className="text-sm leading-relaxed">
              Empowering businesses through innovative software solutions. Your digital transformation partner.
            </p>
            <div className="flex gap-4">
              {[Github, Linkedin, Twitter, Facebook].map((Icon, i) => (
                <a key={i} href="#" className="hover:text-brand-green hover:-translate-y-1 transition-all duration-300 block">
                  <Icon size={20} />
                </a>
              ))}
            </div>
          </div>

          <div className={getFadeInClass(1)} style={styleDelay(1)}>
            <h4 className="text-white font-bold mb-6">Company</h4>
            <ul className="space-y-4">
              {NAV_ITEMS.map((item) => (
                <li key={item.label}>
                  <Link 
                    to={item.href} 
                    onClick={() => handleNavClick(item.href)}
                    className="hover:text-brand-green transition-colors inline-block hover:translate-x-1 duration-200"
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          <div className={getFadeInClass(2)} style={styleDelay(2)}>
            <h4 className="text-white font-bold mb-6">Services</h4>
            <ul className="space-y-4">
              {['Web Development', 'Mobile Apps', 'UI/UX Design', 'Cloud Solutions'].map((s) => (
                <li key={s}><Link to="/services" onClick={() => handleNavClick('/services')} className="hover:text-brand-green transition-colors inline-block hover:translate-x-1 duration-200">{s}</Link></li>
              ))}
            </ul>
          </div>

          <div className={getFadeInClass(3)} style={styleDelay(3)}>
            <h4 className="text-white font-bold mb-6">Newsletter</h4>
            <p className="text-sm mb-4">Subscribe to our newsletter for the latest tech news and updates.</p>
            <form className="flex flex-col gap-3" onSubmit={handleSubscribe}>
              <div className="flex gap-2">
                <input 
                  type="email" 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email address" 
                  className="bg-slate-900 border border-slate-800 rounded-lg px-4 py-2 text-sm w-full focus:outline-none focus:border-brand-blue transition-colors disabled:opacity-50"
                  disabled={subscribeStatus === 'loading' || subscribeStatus === 'success'}
                  required
                />
                <button 
                  type="submit"
                  className={`bg-brand-blue text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-blue/90 transition-all flex items-center justify-center min-w-[3rem] disabled:opacity-70 disabled:cursor-not-allowed`}
                  disabled={subscribeStatus === 'loading' || subscribeStatus === 'success'}
                >
                  {subscribeStatus === 'loading' ? <Loader2 size={16} className="animate-spin" /> : subscribeStatus === 'success' ? <Check size={16} /> : 'OK'}
                </button>
              </div>
              <div className={`overflow-hidden transition-all duration-300 ${subscribeStatus === 'success' ? 'max-h-10 opacity-100' : 'max-h-0 opacity-0'}`}>
                 <p className="text-brand-green text-xs flex items-center gap-1.5 font-medium"><Check size={12} /> Thanks for subscribing!</p>
              </div>
            </form>
          </div>
        </div>

        <div className={`pt-8 border-t border-slate-900 flex flex-col md:flex-row justify-between items-center gap-4 text-sm ${getFadeInClass(4)}`} style={styleDelay(4)}>
          <p>&copy; {new Date().getFullYear()} {COMPANY_NAME}. All rights reserved.</p>
          <div className="flex gap-8">
            <a href="#" className="hover:text-white transition-colors">Privacy Policy</a>
            <a href="#" className="hover:text-white transition-colors">Terms of Service</a>
          </div>
        </div>
      </div>
    </footer>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { CheckCircle2, Lightbulb, Shield, Award, Users, Target, Eye, ChevronLeft, ChevronRight } from 'lucide-react';
import { SectionId } from '../types';
import { TEAM_MEMBERS, CORE_VALUES, COMPANY_NAME } from '../constants';

const valueIconMap: Record<string, React.ReactNode> = {
  Lightbulb: <Lightbulb className="w-8 h-8" />,
  Shield: <Shield className="w-8 h-8" />,
  Award: <Award className="w-8 h-8" />,
  Users: <Users className="w-8 h-8" />,
};

export const About: React.FC = () => {
  const [isSectionVisible, setIsSectionVisible] = useState(false);
  const [isMissionVisible, setIsMissionVisible] = useState(false);
  const [isValuesVisible, setIsValuesVisible] = useState(false);
  const [isTeamVisible, setIsTeamVisible] = useState(false);

  const [currentTeamIndex, setCurrentTeamIndex] = useState(0);
  const [itemsPerSlide, setItemsPerSlide] = useState(3);

  const sectionRef = useRef<HTMLDivElement>(null);
  const missionRef = useRef<HTMLDivElement>(null);
  const valuesRef = useRef<HTMLDivElement>(null);
  const teamRef = useRef<HTMLDivElement>(null);

  const location = useLocation();
  const isPage = location.pathname === '/about';
  const HeadingTag = isPage ? 'h1' : 'h3';

  // Responsive Carousel Logic
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 640) setItemsPerSlide(1);
      else if (window.innerWidth < 1024) setItemsPerSlide(2);
      else setItemsPerSlide(3);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const nextSlide = () => {
    setCurrentTeamIndex((prev) => (prev + 1) % (TEAM_MEMBERS.length - itemsPerSlide + 1));
  };

  const prevSlide = () => {
    setCurrentTeamIndex((prev) => (prev === 0 ? TEAM_MEMBERS.length - itemsPerSlide : prev - 1));
  };

  // Clamping index if window resize makes it invalid
  useEffect(() => {
    const maxIndex = Math.max(0, TEAM_MEMBERS.length - itemsPerSlide);
    if (currentTeamIndex > maxIndex) setCurrentTeamIndex(maxIndex);
  }, [itemsPerSlide, currentTeamIndex]);


  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (entry.target === sectionRef.current) setIsSectionVisible(true);
            if (entry.target === missionRef.current) setIsMissionVisible(true);
            if (entry.target === valuesRef.current) setIsValuesVisible(true);
            if (entry.target === teamRef.current) setIsTeamVisible(true);
          }
        });
      },
      { threshold: 0.15 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);
    if (missionRef.current) observer.observe(missionRef.current);
    if (valuesRef.current) observer.observe(valuesRef.current);
    if (teamRef.current) observer.observe(teamRef.current);

    return () => observer.disconnect();
  }, []);

  return (
    <section id={SectionId.ABOUT} className="py-24 pt-32 bg-white dark:bg-slate-950 min-h-screen transition-colors duration-300">
      <div className="container mx-auto px-6">

        {/* Intro Section */}
        <div ref={sectionRef} className={`flex flex-col lg:flex-row items-center gap-16 transition-all duration-1000 ease-out transform mb-24 ${isSectionVisible ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
          <div className="flex-1 w-full relative">
             <div className="relative aspect-square rounded-3xl overflow-hidden bg-slate-100 dark:bg-slate-800 shadow-2xl">
                <img 
                  src="https://picsum.photos/800/800?random=15" 
                  alt={`Team collaboration at ${COMPANY_NAME} office`} 
                  loading="lazy"
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent flex items-end p-8">
                  <div className="text-white">
                    <p className="text-3xl font-bold">10+</p>
                    <p className="text-sm opacity-80">Years of Excellence</p>
                  </div>
                </div>
             </div>
             {/* Floater */}
             <div className="absolute -bottom-8 -right-8 w-48 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-700 hidden md:block animate-float z-10">
               <p className="text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold mb-2">Projects Completed</p>
               <p className="text-4xl font-bold text-brand-blue">150+</p>
             </div>
          </div>

          <div className="flex-1 space-y-8">
            <div>
              <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">About OITS Dhaka</h2>
              <HeadingTag className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white leading-tight">
                Partnering with startups and enterprises to build the future.
              </HeadingTag>
            </div>

            <p className="text-slate-600 dark:text-slate-300 text-lg leading-relaxed">
              We are a team of passionate developers, designers, and strategists dedicated to delivering digital solutions that make a difference. At OITS Dhaka, we don't just write code; we solve complex business problems through innovation.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {['Agile Methodology', '24/7 Support', 'Dedicated Teams', 'Top-tier Security'].map((item) => (
                <div key={item} className="flex items-center gap-3">
                  <CheckCircle2 className="text-brand-green w-5 h-5 flex-shrink-0" />
                  <span className="font-medium text-slate-800 dark:text-slate-200">{item}</span>
                </div>
              ))}
            </div>

            <div className="pt-4">
               <div className="h-px w-full bg-slate-200 dark:bg-slate-800 mb-8"></div>
               <div className="flex gap-12">
                 <div>
                   <p className="text-3xl font-bold text-slate-900 dark:text-white">50+</p>
                   <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Experts</p>
                 </div>
                 <div>
                   <p className="text-3xl font-bold text-slate-900 dark:text-white">98%</p>
                   <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Client Retention</p>
                 </div>
               </div>
            </div>
          </div>
        </div>

        {/* Mission & Vision */}
        <div ref={missionRef} className={`grid grid-cols-1 md:grid-cols-2 gap-8 mb-24 transition-all duration-1000 ease-out transform ${isMissionVisible ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
          <div className="bg-slate-50 dark:bg-slate-900 p-10 rounded-3xl border border-slate-100 dark:border-slate-800 transition-transform duration-300 hover:-translate-y-1 hover:shadow-lg">
             <div className="w-12 h-12 bg-brand-blue/10 dark:bg-brand-blue/20 text-brand-blue rounded-xl flex items-center justify-center mb-6">
                <Target size={24} />
             </div>
             <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-4">Our Mission</h3>
             <p className="text-slate-600 dark:text-slate-400 leading-relaxed">
               To empower businesses globally by delivering innovative, reliable, and scalable software solutions that drive tangible growth and efficiency.
             </p>
          </div>
          <div className="bg-slate-900 dark:bg-slate-800 p-10 rounded-3xl text-white transition-transform duration-300 hover:-translate-y-1 hover:shadow-2xl shadow-blue-900/20">
             <div className="w-12 h-12 bg-brand-blue text-white rounded-xl flex items-center justify-center mb-6">
                <Eye size={24} />
             </div>
             <h3 className="text-2xl font-bold mb-4">Our Vision</h3>
             <p className="text-slate-300 leading-relaxed">
               To be the most trusted technology partner for organizations seeking to transform their digital presence and operational capabilities.
             </p>
          </div>
        </div>

        {/* Core Values */}
        <div ref={valuesRef} className={`mb-32 transition-all duration-1000 ease-out delay-200 transform ${isValuesVisible ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
          <div className="text-center max-w-2xl mx-auto mb-16">
            <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">Our Culture</h2>
            <h3 className="text-3xl font-bold text-slate-900 dark:text-white">Core Values that drive us.</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
            {CORE_VALUES.map((value, idx) => (
              <div 
                key={idx} 
                className="bg-white dark:bg-slate-900 p-8 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 hover:shadow-xl dark:hover:shadow-blue-900/10 transition-all text-center hover:-translate-y-2 duration-300 group"
                style={{ transitionDelay: `${idx * 100}ms` }}
              >
                <div className="w-16 h-16 mx-auto bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center text-brand-blue mb-6 group-hover:bg-brand-blue group-hover:text-white transition-colors">
                  {valueIconMap[value.icon]}
                </div>
                <h4 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{value.title}</h4>
                <p className="text-sm text-slate-600 dark:text-slate-400">{value.description}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Team Section (Carousel Layout) */}
        <div ref={teamRef} className={`relative transition-all duration-1000 ease-out transform ${isTeamVisible ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
          <div className="flex items-end justify-between mb-16 px-4">
             <div className="max-w-3xl">
                <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">Our Team</h2>
                <h3 className="text-3xl font-bold text-slate-900 dark:text-white">Meet the experts behind our success.</h3>
             </div>
             <div className="flex gap-2">
               <button 
                 onClick={prevSlide}
                 className="p-3 rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 transition-colors"
                 aria-label="Previous team member"
               >
                 <ChevronLeft size={20} />
               </button>
               <button 
                 onClick={nextSlide}
                 className="p-3 rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 transition-colors"
                 aria-label="Next team member"
               >
                 <ChevronRight size={20} />
               </button>
             </div>
          </div>

          <div className="overflow-hidden">
             <div 
               className="flex transition-transform duration-500 ease-in-out"
               style={{ transform: `translateX(-${currentTeamIndex * (100 / itemsPerSlide)}%)` }}
             >
                {TEAM_MEMBERS.map((member) => (
                  <div 
                    key={member.id} 
                    className="flex-shrink-0 px-4"
                    style={{ width: `${100 / itemsPerSlide}%` }}
                  >
                    <div className="group text-center p-6 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl hover:shadow-xl dark:hover:shadow-blue-900/10 hover:-translate-y-2 transition-all duration-300">
                      <div className="relative w-40 h-40 mx-auto mb-6 rounded-full overflow-hidden border-4 border-white dark:border-slate-800 shadow-lg">
                        <img 
                          src={member.image} 
                          alt={`${member.name}, ${member.role} at ${COMPANY_NAME}`}
                          loading="lazy"
                          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                        />
                      </div>
                      <h4 className="text-xl font-bold text-slate-900 dark:text-white">{member.name}</h4>
                      <p className="text-brand-blue font-medium mb-3">{member.role}</p>
                      <p className="text-slate-600 dark:text-slate-400 text-sm max-w-xs mx-auto line-clamp-3">{member.bio}</p>
                    </div>
                  </div>
                ))}
             </div>
          </div>
        </div>

      </div>
    </section>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { ArrowDown, X, ExternalLink, Calendar, Code2, ArrowUpRight, Play, Film, Tag, Volume2, VolumeX } from 'lucide-react';
import { PROJECTS } from '../constants';
import { SectionId, Project } from '../types';
import { Button } from './ui/Button';

// --- Types & Constants ---
const ALL_CATEGORY = 'All';
const ALL_TAG = 'All Tech';

// --- Modal Component ---
interface ProjectModalProps {
  project: Project | null;
  onClose: () => void;
  onProjectSelect: (project: Project) => void;
}

const ProjectModal: React.FC<ProjectModalProps> = ({ project, onClose, onProjectSelect }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [activeProject, setActiveProject] = useState<Project | null>(project);
  const [isClosing, setIsClosing] = useState(false);
  const [isPlayingVideo, setIsPlayingVideo] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (project) {
      setActiveProject(project);
      setIsVisible(true);
      setIsClosing(false);
      setIsPlayingVideo(false);
      document.body.style.overflow = 'hidden';
      if (contentRef.current) contentRef.current.scrollTop = 0;
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [project]);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
      setIsVisible(false);
      onClose();
      setIsClosing(false);
    }, 300); // Match duration of exit animation
  };

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  if (!isVisible || !activeProject) return null;

  const relatedProjects = PROJECTS.filter(
    p => p.category === activeProject.category && p.id !== activeProject.id
  ).slice(0, 3);

  const backdropClass = `fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] transition-opacity duration-300 ease-out ${isClosing ? 'opacity-0' : 'opacity-100'}`;

  const modalContainerClass = `fixed inset-0 z-[101] flex items-center justify-center p-4 sm:p-6 pointer-events-none`;

  const modalContentClass = `relative w-full max-w-5xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] pointer-events-auto transform origin-center transition-all duration-300 ${
    isClosing 
      ? 'opacity-0 scale-95' 
      : 'opacity-100 scale-100 animate-zoom-in'
  }`;

  return (
    <>
      <div className={backdropClass} onClick={handleClose} />
      <div className={modalContainerClass}>
        <div className={modalContentClass}>

          {/* Scrollable Container */}
          <div ref={contentRef} className="overflow-y-auto custom-scrollbar scroll-smooth">

            {/* Header Media */}
            <div className="relative h-64 md:h-96 shrink-0 group bg-slate-900">
               {isPlayingVideo && activeProject.demoVideoUrl ? (
                 <div className="w-full h-full flex items-center justify-center bg-black relative">
                   <video 
                     src={activeProject.demoVideoUrl} 
                     controls 
                     autoPlay 
                     className="w-full h-full object-contain focus:outline-none"
                   >
                      {activeProject.captionsUrl && (
                          <track kind="captions" src={activeProject.captionsUrl} srcLang="en" label="English" default />
                      )}
                      Your browser does not support the video tag.
                   </video>
                   <button 
                     onClick={() => setIsPlayingVideo(false)}
                     className="absolute top-4 left-4 px-4 py-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white text-sm font-medium transition-colors z-20 flex items-center gap-2 group/back"
                   >
                     <ArrowDown className="w-4 h-4 rotate-90 group-hover/back:-translate-x-1 transition-transform" />
                     Back
                   </button>
                 </div>
               ) : (
                 <>
                  <img 
                    src={activeProject.imageUrl} 
                    alt={activeProject.title} 
                    className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105 opacity-90 group-hover:opacity-100"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-slate-900/20 to-transparent" />

                  {activeProject.demoVideoUrl && (
                    <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
                       <button 
                         onClick={() => setIsPlayingVideo(true)}
                         className="pointer-events-auto flex items-center gap-2 px-6 py-3 bg-white/20 hover:bg-white/30 backdrop-blur-md border border-white/40 rounded-full text-white font-bold transition-all hover:scale-105 group/play shadow-xl"
                       >
                         <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-brand-blue group-hover/play:scale-110 transition-transform">
                           <Play size={16} fill="currentColor" />
                         </div>
                         Watch Demo
                       </button>
                    </div>
                  )}
                 </>
               )}

              {!isPlayingVideo && (
                <button 
                  onClick={handleClose}
                  className="absolute top-4 right-4 p-2 bg-black/20 hover:bg-black/40 backdrop-blur-md rounded-full text-white transition-colors z-30"
                  aria-label="Close modal"
                >
                  <X size={24} />
                </button>
              )}

              {!isPlayingVideo && (
                <div className="absolute bottom-0 left-0 right-0 p-8 text-white z-20 pointer-events-none">
                  <span className="inline-block px-3 py-1 bg-brand-blue rounded-full text-xs font-semibold uppercase tracking-wider mb-3 shadow-sm border border-blue-500/50">
                    {activeProject.category}
                  </span>
                  <h3 className="text-3xl md:text-5xl font-bold mb-2 tracking-tight">{activeProject.title}</h3>
                </div>
              )}
            </div>

            {/* Body Content */}
            <div className="p-8 md:p-12">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-12">

                {/* Main Description */}
                <div className="md:col-span-2 space-y-8">
                  <div>
                    <h4 className="text-xl font-bold text-slate-900 dark:text-white mb-4">Project Overview</h4>
                    <p className="text-slate-600 dark:text-slate-300 leading-relaxed text-lg">
                      {activeProject.fullDescription || activeProject.description}
                    </p>
                  </div>

                  {activeProject.technologies && (
                    <div>
