              className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 transform ${
                activeCategory === cat
                  ? 'bg-brand-blue text-white shadow-lg scale-105 ring-2 ring-brand-blue ring-offset-2 ring-offset-slate-50 dark:ring-offset-slate-900'
                  : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 hover:scale-105'
