```tsx
import React, { useRef, useEffect, useState } from 'react';
import { SectionTitle, SectionParagraph } from '../ui/typography';
import { SERVICES } from '../../data';
import { Card } from './Card';

export const Services: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }
    return () => observer.disconnect();
  }, []);

  const getAnim = (delay: number) => {
    return `animate-fade-in-up duration-1000 ${
      isVisible ? 'opacity-100' : 'opacity-0'
    } delay-${delay * 100}ms`;
  };

  return (
    <section ref={sectionRef} className="py-20 lg:py-32">
      <div className="container mx-auto px-4">
        <div className="text-center mb-16">
          <SectionTitle
            className={`${isVisible ? 'animate-fade-in-up opacity-100' : 'opacity-0'} duration-1000`}
          >
            Our Services
          </SectionTitle>
          <SectionParagraph
            className={`mt-4 ${isVisible ? 'animate-fade-in-up opacity-100' : 'opacity-0'} duration-1000`}
          >
            We offer the following services.
          </SectionParagraph>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {SERVICES.map((service, index) => (
            <Card
              key={service.id}
              title={service.title}
              description={service.description}
              icon={service.icon}
              className={getAnim(index + 1)} // Use getAnim with index
            />
          ))}
        </div>
      </div>
    </section>
  );
};
```


