import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { ArrowDown, X, ExternalLink, Calendar, Code2, ArrowUpRight, Play, Film, Tag, Volume2, VolumeX } from 'lucide-react';
import { PROJECTS } from '../constants';
import { SectionId, Project } from '../types';
import { Button } from './ui/Button';

// --- Types & Constants ---
const ALL_CATEGORY = 'All';
const ALL_TAG = 'All Tech';

// --- Modal Component ---
interface ProjectModalProps {
  project: Project | null;
  onClose: () => void;
  onProjectSelect: (project: Project) => void;
}

const ProjectModal: React.FC<ProjectModalProps> = ({ project, onClose, onProjectSelect }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [activeProject, setActiveProject] = useState<Project | null>(project);
  const [isClosing, setIsClosing] = useState(false);
  const [isPlayingVideo, setIsPlayingVideo] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (project) {
      setActiveProject(project);
      setIsVisible(true);
      setIsClosing(false);
      setIsPlayingVideo(false);
      document.body.style.overflow = 'hidden';
      if (contentRef.current) contentRef.current.scrollTop = 0;
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [project]);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
      setIsVisible(false);
      onClose();
      setIsClosing(false);
    }, 300); // Match duration of exit animation
  };

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  if (!isVisible || !activeProject) return null;

  const relatedProjects = PROJECTS.filter(
    p => p.category === activeProject.category && p.id !== activeProject.id
  ).slice(0, 3);

  const backdropClass = `fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] transition-opacity duration-300 ease-out ${isClosing ? 'opacity-0' : 'opacity-100'}`;

  const modalContainerClass = `fixed inset-0 z-[101] flex items-center justify-center p-4 sm:p-6 pointer-events-none`;

  const modalContentClass = `relative w-full max-w-5xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] pointer-events-auto transform origin-center transition-all duration-300 ${
    isClosing 
      ? 'opacity-0 scale-95' 
      : 'opacity-100 scale-100 animate-zoom-in'
  }`;

  return (
    <>
      <div className={backdropClass} onClick={handleClose} />
      <div className={modalContainerClass}>
        <div className={modalContentClass}>

          {/* Scrollable Container */}
          <div ref={contentRef} className="overflow-y-auto custom-scrollbar scroll-smooth">

            {/* Header Media */}
            <div className="relative h-64 md:h-96 shrink-0 group bg-slate-900">
               {isPlayingVideo && activeProject.demoVideoUrl ? (
                 <div className="w-full h-full flex items-center justify-center bg-black relative">
                   <video 
                     src={activeProject.demoVideoUrl} 
                     controls 
                     autoPlay 
                     className="w-full h-full object-contain focus:outline-none"
                   >
                      {activeProject.captionsUrl && (
                          <track kind="captions" src={activeProject.captionsUrl} srcLang="en" label="English" default />
                      )}
                      Your browser does not support the video tag.
                   </video>
                   <button 
                     onClick={() => setIsPlayingVideo(false)}
                     className="absolute top-4 left-4 px-4 py-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white text-sm font-medium transition-colors z-20 flex items-center gap-2 group/back"
                   >
                     <ArrowDown className="w-4 h-4 rotate-90 group-hover/back:-translate-x-1 transition-transform" />
                     Back
                   </button>
                 </div>
               ) : (
                 <>
                  <img 
                    src={activeProject.imageUrl} 
                    alt={activeProject.title} 
                    className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105 opacity-90 group-hover:opacity-100"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-slate-900/20 to-transparent" />

                  {activeProject.demoVideoUrl && (
                    <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
                       <button 
                         onClick={() => setIsPlayingVideo(true)}
                         className="pointer-events-auto flex items-center gap-2 px-6 py-3 bg-white/20 hover:bg-white/30 backdrop-blur-md border border-white/40 rounded-full text-white font-bold transition-all hover:scale-105 group/play shadow-xl"
                       >
                         <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-brand-blue group-hover/play:scale-110 transition-transform">
                           <Play size={16} fill="currentColor" />
                         </div>
                         Watch Demo
                       </button>
                    </div>
                  )}
                 </>
               )}

              {!isPlayingVideo && (
                <button 
                  onClick={handleClose}
                  className="absolute top-4 right-4 p-2 bg-black/20 hover:bg-black/40 backdrop-blur-md rounded-full text-white transition-colors z-30"
                  aria-label="Close modal"
                >
                  <X size={24} />
                </button>
              )}

              {!isPlayingVideo && (
                <div className="absolute bottom-0 left-0 right-0 p-8 text-white z-20 pointer-events-none">
                  <span className="inline-block px-3 py-1 bg-brand-blue rounded-full text-xs font-semibold uppercase tracking-wider mb-3 shadow-sm border border-blue-500/50">
                    {activeProject.category}
                  </span>
                  <h3 className="text-3xl md:text-5xl font-bold mb-2 tracking-tight">{activeProject.title}</h3>
                </div>
              )}
            </div>

            {/* Body Content */}
            <div className="p-8 md:p-12">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-12">

                {/* Main Description */}
                <div className="md:col-span-2 space-y-8">
                  <div>
                    <h4 className="text-xl font-bold text-slate-900 dark:text-white mb-4">Project Overview</h4>
                    <p className="text-slate-600 dark:text-slate-300 leading-relaxed text-lg">
                      {activeProject.fullDescription || activeProject.description}
                    </p>
                  </div>

                  {activeProject.technologies && (
                    <div>
                      <h4 className="text-lg font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                        <Code2 size={20} className="text-brand-blue" />
                        Technologies Used
                      </h4>
                      <div className="flex flex-wrap gap-2">
                        {activeProject.technologies.map((tech) => (
                          <span key={tech} className="px-4 py-2 bg-slate-50 dark:bg-slate-800 text-slate-700 dark:text-slate-200 rounded-lg text-sm font-medium border border-slate-200 dark:border-slate-700 hover:border-brand-blue/30 transition-colors cursor-default">
                            {tech}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Sidebar Details */}
                <div className="space-y-6">
                   <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 sticky top-6">
                      <h4 className="font-bold text-slate-900 dark:text-white mb-6 text-lg">At a Glance</h4>
                      <ul className="space-y-4 text-sm">
                        <li className="flex flex-col pb-4 border-b border-slate-200 dark:border-slate-700 last:border-0 last:pb-0">
                          <span className="text-slate-500 dark:text-slate-400 mb-1">Client</span>
                          <span className="font-semibold text-slate-900 dark:text-white">Confidential Partner</span>
                        </li>
                        <li className="flex flex-col pb-4 border-b border-slate-200 dark:border-slate-700 last:border-0 last:pb-0">
                          <span className="text-slate-500 dark:text-slate-400 mb-1">Timeline</span>
                          <span className="font-semibold text-slate-900 dark:text-white flex items-center gap-2">
                             <Calendar size={14} className="text-brand-blue"/> 3 Months
                          </span>
                        </li>
                        <li className="flex flex-col pb-4 border-b border-slate-200 dark:border-slate-700 last:border-0 last:pb-0">
                          <span className="text-slate-500 dark:text-slate-400 mb-1">Services</span>
                          <span className="font-semibold text-slate-900 dark:text-white">{activeProject.category}</span>
                        </li>
                      </ul>

                      <Button className="w-full mt-8 flex items-center justify-center gap-2 shadow-lg shadow-blue-900/20 group" variant="primary" onClick={() => window.open(activeProject.link || '#', '_blank')}>
                        Visit Live Site <ExternalLink size={16} className="group-hover:translate-x-1 transition-transform" />
                      </Button>
                   </div>
                </div>
              </div>

              {/* Related Projects */}
              {relatedProjects.length > 0 && (
                <div className="mt-16 pt-10 border-t border-slate-100 dark:border-slate-800">
                  <h4 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">Related Projects</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                    {relatedProjects.map((relProject) => (
                      <div 
                        key={relProject.id} 
                        className="group cursor-pointer"
                        onClick={() => onProjectSelect(relProject)}
                      >
                        <div className="relative aspect-video rounded-xl overflow-hidden mb-3 border border-slate-100 dark:border-slate-700">
                          <img 
                            src={relProject.imageUrl} 
                            alt={relProject.title}
                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                          />
                          <div className="absolute inset-0 bg-slate-900/60 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center z-10 backdrop-blur-[1px]">
                            <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 bg-white text-slate-900 px-4 py-2 rounded-full font-bold text-xs shadow-xl flex items-center gap-1">
                              View Project <ArrowUpRight size={14} />
                            </div>
                          </div>
                        </div>
                        <h5 className="font-bold text-slate-900 dark:text-white group-hover:text-brand-purple transition-colors">{relProject.title}</h5>
                        <p className="text-xs text-slate-500 dark:text-slate-400">{relProject.category}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

// --- Project Card Component ---
interface ProjectCardProps {
  project: Project;
  onClick: () => void;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onClick }) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const [shouldLoadVideo, setShouldLoadVideo] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (cardRef.current) observer.observe(cardRef.current);
    return () => { if (cardRef.current) observer.unobserve(cardRef.current); };
  }, []);

  const handleMouseEnter = () => {
    setIsHovered(true);
    if (project.demoVideoUrl) {
      setShouldLoadVideo(true);
      setTimeout(() => {
        if (videoRef.current) {
            videoRef.current.currentTime = 0;
            videoRef.current.play().catch(() => {});
        }
      }, 0);
    }
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    if (project.demoVideoUrl && videoRef.current) videoRef.current.pause();
  };

  return (
    <div 
      ref={cardRef}
      className={`group bg-white dark:bg-slate-900 rounded-2xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm hover:shadow-2xl dark:hover:shadow-blue-900/10 transition-all duration-700 ease-out transform ${
        isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
      }`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-slate-200 dark:bg-slate-800">
        <div ref={wrapperRef} className="absolute inset-0 h-[120%] -top-[10%] w-full will-change-transform">
          <img src={project.imageUrl} alt={project.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"/>
        </div>

        {/* Video Preview */}
        {project.demoVideoUrl && shouldLoadVideo && (
            <video
                ref={videoRef}
                src={project.demoVideoUrl}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 pointer-events-none ${isHovered ? 'opacity-100' : 'opacity-0'}`}
                muted={isMuted}
                loop
                playsInline
            />
        )}

        {/* Visual Indicator for Video (Badge) */}
        {!isHovered && project.demoVideoUrl && (
          <div className="absolute top-3 right-3 z-10 bg-slate-900/60 backdrop-blur-md p-1.5 rounded-full text-white/90 border border-white/10 shadow-lg animate-fade-in">
             <Film size={14} />
          </div>
        )}

        {/* Volume Control (visible on hover) */}
        {project.demoVideoUrl && shouldLoadVideo && isHovered && (
            <button 
                onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
                className="absolute top-4 right-4 z-20 p-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white transition-all hover:scale-110 animate-fade-in"
                title={isMuted ? "Unmute" : "Mute"}
            >
                {isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>
        )}

        {/* Hover Overlay */}
        <div className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center z-10 cursor-pointer backdrop-blur-[2px] ${project.demoVideoUrl && isHovered ? 'bg-slate-900/40' : 'bg-slate-900/70'}`} onClick={onClick}>
          <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-75 flex flex-col items-center gap-3">
            <button className="bg-white text-slate-900 px-6 py-3 rounded-full font-bold text-sm shadow-xl hover:bg-brand-purple hover:text-white flex items-center gap-2 group/btn transition-colors animate-subtle-pulse">
              View Case Study <ArrowUpRight size={18} />
            </button>
          </div>
        </div>
      </div>
      <div className="p-6 relative z-20 bg-white dark:bg-slate-900">
        <div className="flex items-start justify-between mb-3">
           <span className="px-2 py-1 bg-brand-blue/10 dark:bg-brand-blue/20 text-brand-blue dark:text-brand-blue rounded text-[10px] font-bold uppercase tracking-wider">{project.category}</span>
        </div>
        <h4 className="text-xl font-bold text-slate-900 dark:text-white mb-2 group-hover:text-brand-purple transition-colors">{project.title}</h4>
        <p className="text-slate-600 dark:text-slate-400 text-sm line-clamp-2">{project.description}</p>
      </div>
    </div>
  );
};

// --- Main Portfolio Component ---
export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(ALL_TAG);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [visibleCount, setVisibleCount] = useState(6);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);
  const location = useLocation();
  const isPage = location.pathname === '/portfolio';
  const HeadingTag = isPage ? 'h1' : 'h3';

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) observer.disconnect();
    };
  }, []);

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const allTags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];

  const getCategoryCount = (cat: string) => cat === ALL_CATEGORY ? PROJECTS.length : PROJECTS.filter(p => p.category === cat).length;
  const getTagCount = (tag: string) => tag === ALL_TAG ? PROJECTS.length : PROJECTS.filter(p => p.technologies && p.technologies.includes(tag)).length;

  const filteredProjects = PROJECTS.filter(p => {
    return (activeCategory === ALL_CATEGORY || p.category === activeCategory) && 
           (activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag)));
  });

  const displayedProjects = filteredProjects.slice(0, visibleCount);

  const getFadeInClass = (delay: number) => 
    `transition-all duration-700 ease-out transform ${
      isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
    }`;

  return (
    <section ref={sectionRef} id={SectionId.PORTFOLIO} className="py-24 pt-32 bg-slate-50 dark:bg-slate-950 min-h-screen">
      <div className="container mx-auto px-6">
        <div className={`text-center max-w-3xl mx-auto mb-12 ${getFadeInClass(0)}`}>
          <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">{isPage ? 'Portfolio' : 'Featured Work'}</h2>
          <HeadingTag className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white leading-tight mb-4">
            Showcasing our success stories.
          </HeadingTag>
          <p className="text-slate-600 dark:text-slate-400 text-lg">
            From concept to launch, we've helped businesses across the globe achieve their digital goals.
          </p>
        </div>

        {/* Category Filters */}
        <div className={`flex flex-wrap justify-center gap-3 mb-8 ${getFadeInClass(0)}`} style={{ transitionDelay: '100ms' }}>
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => { setActiveCategory(cat); setVisibleCount(6); }}
              className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 transform ${
                activeCategory === cat
                  ? 'bg-brand-blue text-white shadow-lg scale-105 ring-2 ring-brand-blue ring-offset-2 ring-offset-slate-50 dark:ring-offset-slate-900'
                  : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 hover:scale-105'
              }`}
            >
              {cat} <span className={`ml-2 text-xs font-bold ${activeCategory === cat ? 'text-slate-200' : 'text-slate-500'}`}>{getCategoryCount(cat)}</span>
            </button>
          ))}
        </div>

        {/* Tag Filters */}
        <div className={`flex items-center justify-center gap-2 mb-12 overflow-x-auto no-scrollbar py-2 px-4 max-w-5xl mx-auto ${getFadeInClass(0)}`} style={{ transitionDelay: '200ms' }}>
          <div className="flex items-center gap-2 bg-white/50 dark:bg-slate-900/50 p-2 rounded-full border border-slate-200 dark:border-slate-800 backdrop-blur-sm">
             <Tag size={16} className="text-slate-400 ml-2" />
             {allTags.map((tag) => (
              <button
                key={tag}
                onClick={() => { setActiveTag(tag); setVisibleCount(6); }}
                className={`px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 whitespace-nowrap flex items-center gap-1 ${
                  activeTag === tag
                    ? 'bg-slate-800 dark:bg-slate-700 text-white shadow-md'
                    : 'bg-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-800'
                }`}
              >
                {tag} <span className="text-[10px] opacity-70">{getTagCount(tag)}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 min-h-[400px]">
          {displayedProjects.map((project) => (
            <ProjectCard key={project.id} project={project} onClick={() => setSelectedProject(project)} />
          ))}
          {displayedProjects.length === 0 && (
            <div className="col-span-full flex flex-col items-center justify-center text-slate-400 py-12">
               <div className="w-16 h-16 bg-slate-100 dark:bg-slate-900 rounded-full flex items-center justify-center mb-4"><Code2 className="w-8 h-8 text-slate-300" /></div>
               <p className="font-medium">No projects found.</p>
               <button onClick={() => { setActiveCategory(ALL_CATEGORY); setActiveTag(ALL_TAG); }} className="mt-4 text-brand-blue text-sm hover:underline">Clear all filters</button>
            </div>
          )}
        </div>

        {visibleCount < filteredProjects.length && (
          <div className={`mt-16 text-center ${getFadeInClass(0)}`}>
            <Button variant="outline" onClick={() => setVisibleCount(p => p + 3)} className="group px-8 dark:text-slate-300 dark:border-slate-700 dark:hover:bg-slate-800">
              View More Projects <ArrowDown className="ml-2 w-4 h-4 transition-transform group-hover:translate-y-1" />
            </Button>
          </div>
        )}
      </div>

      <ProjectModal project={selectedProject} onClose={() => setSelectedProject(null)} onProjectSelect={setSelectedProject} />
    </section>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Mail, MapPin, Phone, Send, AlertCircle, CheckCircle2, Loader2, Clock } from 'lucide-react';
import { Button } from './ui/Button';
import { ADDRESS, CONTACT_EMAIL } from '../constants';
import { SectionId } from '../types';

interface FormData {
  name: string;
  email: string;
  subject: string;
  message: string;
}

interface FormErrors {
  name?: string;
  email?: string;
  subject?: string;
  message?: string;
}

export const Contact: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({ name: '', email: '', subject: '', message: '' });
  const [errors, setErrors] = useState<FormErrors>({});
  const [status, setStatus] = useState<'idle' | 'sending' | 'success'>('idle');
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  const location = useLocation();
  const isPage = location.pathname === '/contact';
  const HeadingTag = isPage ? 'h1' : 'h3';

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) observer.unobserve(sectionRef.current);
    };
  }, []);

  const validateField = (name: string, value: string): string | undefined => {
    switch (name) {
      case 'name':
        return !value.trim() ? 'Name is required' : undefined;
      case 'email':
        if (!value.trim()) return 'Email is required';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return 'Invalid email address';
        return undefined;
      case 'subject':
        return !value.trim() ? 'Subject is required' : undefined;
      case 'message':
        return !value.trim() ? 'Message is required' : undefined;
      default:
        return undefined;
    }
  };

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};
    let isValid = true;

    (Object.keys(formData) as Array<keyof FormData>).forEach((key) => {
      const error = validateField(key, formData[key]);
      if (error) {
        newErrors[key] = error;
        isValid = false;
      }
    });

    setErrors(newErrors);
    return isValid;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setStatus('sending');
    // Simulate API call
    setTimeout(() => {
      setStatus('success');
      setFormData({ name: '', email: '', subject: '', message: '' });
      setErrors({});
      setTimeout(() => setStatus('idle'), 5000);
    }, 1500);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { id, value } = e.target;
    setFormData(prev => ({ ...prev, [id]: value }));

    // Real-time validation
    const error = validateField(id, value);
    setErrors(prev => ({
      ...prev,
      [id]: error
    }));
  };

  // Animation helper
  const getAnimationClass = (delay: number) => 
    `transition-all duration-700 ease-out transform will-change-transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`;

  return (
    <section id={SectionId.CONTACT} className="py-24 pt-32 bg-slate-900 text-white relative overflow-hidden min-h-screen" ref={sectionRef}>
      <div className="container mx-auto px-6 relative z-10">

        <div className={`text-center max-w-3xl mx-auto mb-16 ${getAnimationClass(0)}`}>
          <h2 className="text-sm font-bold text-brand-green uppercase tracking-widest mb-3">Contact Us</h2>
          <HeadingTag className="text-3xl md:text-5xl font-bold leading-tight mb-6">
            Let's Start a Conversation.
          </HeadingTag>
          <p className="text-slate-400 text-lg">
            Whether you have a question about our services, pricing, or need a custom solution, our team is ready to answer all your questions.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-16">
          <div className={`bg-slate-800 p-8 rounded-2xl border border-slate-700 hover:border-brand-blue/50 transition-colors ${getAnimationClass(100)}`} style={{ transitionDelay: '100ms' }}>
            <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-brand-green mb-6">
              <Mail size={24} />
            </div>
            <h4 className="text-xl font-bold mb-2">Email Us</h4>
            <p className="text-slate-400 text-sm mb-4">Our team is here to help.</p>
            <p className="font-semibold text-brand-green">{CONTACT_EMAIL}</p>
          </div>

          <div className={`bg-slate-800 p-8 rounded-2xl border border-slate-700 hover:border-brand-blue/50 transition-colors ${getAnimationClass(200)}`} style={{ transitionDelay: '200ms' }}>
            <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-brand-green mb-6">
              <MapPin size={24} />
            </div>
            <h4 className="text-xl font-bold mb-2">Visit Us</h4>
            <p className="text-slate-400 text-sm mb-4">Come say hello at our office.</p>
            <p className="font-semibold text-brand-green">{ADDRESS}</p>
          </div>

          <div className={`bg-slate-800 p-8 rounded-2xl border border-slate-700 hover:border-brand-blue/50 transition-colors ${getAnimationClass(300)}`} style={{ transitionDelay: '300ms' }}>
             <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-brand-green mb-6">
               <Phone size={24} />
             </div>
             <h4 className="text-xl font-bold mb-2">Call Us</h4>
             <p className="text-slate-400 text-sm mb-4">Mon-Fri from 8am to 5pm.</p>
             <p className="font-semibold text-brand-green">+880 1234 567890</p>
          </div>
        </div>

        <div className={`grid grid-cols-1 lg:grid-cols-2 gap-12 bg-slate-800/30 p-8 md:p-12 rounded-3xl border border-slate-800 ${getAnimationClass(400)}`} style={{ transitionDelay: '400ms' }}>

           {/* Contact Form */}
           <div>
             <h3 className="text-2xl font-bold mb-6">Send us a message</h3>
             {status === 'success' && (
                <div className="bg-brand-green/10 border border-brand-green/20 rounded-lg p-4 mb-6 flex items-start gap-3 animate-slide-in-top">
                  <CheckCircle2 className="text-brand-green shrink-0 mt-0.5" size={18} />
                  <div>
                    <h4 className="text-brand-green font-semibold text-sm">Message Sent Successfully!</h4>
                    <p className="text-brand-green/80 text-xs mt-1">We'll get back to you within 24 hours.</p>
                  </div>
                </div>
             )}

             <form onSubmit={handleSubmit} className="space-y-6" noValidate>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                   <label htmlFor="name" className="text-sm font-medium text-slate-300">Name</label>
                   <input 
                      type="text" 
                      id="name"
                      disabled={status === 'sending'}
                      className={`w-full bg-slate-900 border rounded-lg px-4 py-3 text-white focus:outline-none transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${errors.name ? 'border-red-500 focus:border-red-500' : 'border-slate-700 focus:border-brand-blue'}`}
                      placeholder="John Doe"
                      value={formData.name}
                      onChange={handleChange}
                   />
                   {errors.name && <p className="text-red-400 text-xs flex items-center mt-1"><AlertCircle size={12} className="mr-1"/> {errors.name}</p>}
                 </div>
                 <div className="space-y-2">
                   <label htmlFor="email" className="text-sm font-medium text-slate-300">Email</label>
                   <input 
                      type="email" 
                      id="email"
                      disabled={status === 'sending'}
                      className={`w-full bg-slate-900 border rounded-lg px-4 py-3 text-white focus:outline-none transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${errors.email ? 'border-red-500 focus:border-red-500' : 'border-slate-700 focus:border-brand-blue'}`}
                      placeholder="john@example.com"
                      value={formData.email}
                      onChange={handleChange}
                   />
                   {errors.email && <p className="text-red-400 text-xs flex items-center mt-1"><AlertCircle size={12} className="mr-1"/> {errors.email}</p>}
                 </div>
               </div>

               <div className="space-y-2">
                 <label htmlFor="subject" className="text-sm font-medium text-slate-300">Subject</label>
                 <input 
                    type="text" 
                    id="subject"
                    disabled={status === 'sending'}
                    className={`w-full bg-slate-900 border rounded-lg px-4 py-3 text-white focus:outline-none transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${errors.subject ? 'border-red-500 focus:border-red-500' : 'border-slate-700 focus:border-brand-blue'}`}
                    placeholder="Project Inquiry"
                    value={formData.subject}
                    onChange={handleChange}
                 />
                 {errors.subject && <p className="text-red-400 text-xs flex items-center mt-1"><AlertCircle size={12} className="mr-1"/> {errors.subject}</p>}
               </div>

               <div className="space-y-2">
                 <label htmlFor="message" className="text-sm font-medium text-slate-300">Message</label>
                 <textarea 
                    id="message"
                    rows={4}
                    disabled={status === 'sending'}
                    className={`w-full bg-slate-900 border rounded-lg px-4 py-3 text-white focus:outline-none transition-colors resize-none disabled:opacity-50 disabled:cursor-not-allowed ${errors.message ? 'border-red-500 focus:border-red-500' : 'border-slate-700 focus:border-brand-blue'}`}
                    placeholder="Tell us about your project..."
                    value={formData.message}
                    onChange={handleChange}
                 />
                 {errors.message && <p className="text-red-400 text-xs flex items-center mt-1"><AlertCircle size={12} className="mr-1"/> {errors.message}</p>}
               </div>

               <div>
                 <Button 
                   type="submit" 
                   variant="primary" 
                   size="lg" 
                   className="w-full bg-brand-blue hover:bg-brand-blue/90 border-none disabled:bg-blue-800 disabled:opacity-70 disabled:cursor-not-allowed"
                   disabled={status === 'sending'}
                 >
                   {status === 'sending' ? (
                     <span className="flex items-center">
                       <Loader2 className="animate-spin mr-2 h-4 w-4" />
                       Sending...
                     </span>
                   ) : status === 'success' ? 'Message Sent!' : (
                     <span className="flex items-center">
                       Send Message <Send className="ml-2 w-4 h-4" />
                     </span>
                   )}
                 </Button>
               </div>
             </form>
           </div>

           {/* Map Placeholder */}
           <div className="h-full min-h-[400px] bg-slate-900 rounded-xl overflow-hidden relative">
             <iframe 
               src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3651.902442430136!2d90.39108331536293!3d23.75085809467772!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3755b888ad3b91bf%3A0xb00b1297e6466f8!2sKarwan%20Bazar%2C%20Dhaka%201215!5e0!3m2!1sen!2sbd!4v1646808542314!5m2!1sen!2sbd" 
               width="100%" 
               height="100%" 
               style={{ border: 0 }} 
               allowFullScreen 
               loading="lazy"
               className="grayscale opacity-70 hover:grayscale-0 hover:opacity-100 transition-all duration-500"
             ></iframe>
             <div className="absolute bottom-4 left-4 bg-slate-900/90 backdrop-blur p-4 rounded-lg border border-slate-700">
               <div className="flex items-center gap-2 text-sm font-medium">
                 <Clock size={16} className="text-brand-green"/>
                 <span>9:00 AM - 6:00 PM (Sun-Thu)</span>
               </div>
             </div>
           </div>

        </div>
      </div>
    </section>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { ArrowDown, X, ExternalLink, Calendar, Code2, ArrowUpRight, Play, Film, Tag, Volume2, VolumeX } from 'lucide-react';
import { PROJECTS } from '../constants';
import { SectionId, Project } from '../types';
import { Button } from './ui/Button';

// --- Types & Constants ---
const ALL_CATEGORY = 'All';
const ALL_TAG = 'All Tech';

// --- Modal Component ---
interface ProjectModalProps {
  project: Project | null;
  onClose: () => void;
  onProjectSelect: (project: Project) => void;
}

const ProjectModal: React.FC<ProjectModalProps> = ({ project, onClose, onProjectSelect }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [activeProject, setActiveProject] = useState<Project | null>(project);
  const [isClosing, setIsClosing] = useState(false);
  const [isPlayingVideo, setIsPlayingVideo] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (project) {
      setActiveProject(project);
      setIsVisible(true);
      setIsClosing(false);
      setIsPlayingVideo(false);
      document.body.style.overflow = 'hidden';
      if (contentRef.current) contentRef.current.scrollTop = 0;
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [project]);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
      setIsVisible(false);
      onClose();
      setIsClosing(false);
    }, 300); // Match duration of exit animation
  };

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  if (!isVisible || !activeProject) return null;

  const relatedProjects = PROJECTS.filter(
    p => p.category === activeProject.category && p.id !== activeProject.id
  ).slice(0, 3);

  const backdropClass = `fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] transition-opacity duration-300 ease-out ${isClosing ? 'opacity-0' : 'opacity-100'}`;

  const modalContainerClass = `fixed inset-0 z-[101] flex items-center justify-center p-4 sm:p-6 pointer-events-none`;

  const modalContentClass = `relative w-full max-w-5xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] pointer-events-auto transform origin-center transition-all duration-300 ${
    isClosing 
      ? 'opacity-0 scale-95' 
      : 'opacity-100 scale-100 animate-zoom-in'
  }`;

  return (
    <>
      <div className={backdropClass} onClick={handleClose} />
      <div className={modalContainerClass}>
        <div className={modalContentClass}>

          {/* Scrollable Container */}
          <div ref={contentRef} className="overflow-y-auto custom-scrollbar scroll-smooth">

            {/* Header Media */}
            <div className="relative h-64 md:h-96 shrink-0 group bg-slate-900">
               {isPlayingVideo && activeProject.demoVideoUrl ? (
                 <div className="w-full h-full flex items-center justify-center bg-black relative">
                   <video 
                     src={activeProject.demoVideoUrl} 
                     controls 
                     autoPlay 
                     className="w-full h-full object-contain focus:outline-none"
                   >
                      {activeProject.captionsUrl && (
                          <track kind="captions" src={activeProject.captionsUrl} srcLang="en" label="English" default />
                      )}
                      Your browser does not support the video tag.
                   </video>
                   <button 
                     onClick={() => setIsPlayingVideo(false)}
                     className="absolute top-4 left-4 px-4 py-2 bg-black/60 hover:bg-black/80 backdrop-blur-md rounded-full text-white text-sm font-medium transition-colors z-20 flex items-center gap-2 group/back"
                   >
                     <ArrowDown className="w-4 h-4 rotate-90 group-hover/back:-translate-x-1 transition-transform" />
                     Back
                   </button>
                 </div>
               ) : (
                 <>
                  <img 
                    src={activeProject.imageUrl} 
                    alt={activeProject.title} 
                    className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105 opacity-90 group-hover:opacity-100"
                  />
