            </div>
          </div>
          <div className={`flex-1 w-full max-w-xl lg:max-w-none transition-all duration-1000 delay-500 ease-out ${isVisible ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-12'}`}>
