  const getCategoryCount = (cat: string) => {
    // If filtering by tag, the category count should reflect that tag context (optional, but requested "dynamic")
    // If we want "pure" category count regardless of current tag selection:
    // return cat === ALL_CATEGORY ? PROJECTS.length : PROJECTS.filter(p => p.category === cat).length;

    // If we want "context-aware" category count (i.e. how many projects in this category match the CURRENT activeTag):
    const projectsWithTag = activeTag === ALL_TAG ? PROJECTS : PROJECTS.filter(p => p.technologies?.includes(activeTag));
    return cat === ALL_CATEGORY ? projectsWithTag.length : projectsWithTag.filter(p => p.category === cat).length;
  };

  const getTagCount = (tag: string) => {
     // Dynamic: How many projects with this tag exist in the CURRENT activeCategory
     const projectsInCategory = activeCategory === ALL_CATEGORY ? PROJECTS : PROJECTS.filter(p => p.category === activeCategory);
     return tag === ALL_TAG ? projectsInCategory.length : projectsInCategory.filter(p => p.technologies?.includes(tag)).length;
  };

  // Filter projects
  const filteredProjects = PROJECTS.filter(p => {
    const categoryMatch = activeCategory === ALL_CATEGORY || p.category === activeCategory;
    const tagMatch = activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag));
    return categoryMatch && tagMatch;
  });

  const displayedProjects = filteredProjects.slice(0, visibleCount);
  const hasMore = visibleCount < filteredProjects.length;

  const handleLoadMore = () => {
    setVisibleCount(prev => prev + 3);
  };

  const handleCategoryChange = (cat: string) => {
    if (activeCategory === cat) return;
    setIsAnimating(true);
    setTimeout(() => {
        setActiveCategory(cat);
        setVisibleCount(6);
        // We do not reset Tag here to allow cross-filtering, or we could reset it. 
        // Typically good UX to keep it if possible, but "All Tech" is safer.
        // Let's keep tag active to show dynamic counts working.
        setTimeout(() => setIsAnimating(false), 50);
    }, 300);
  };

  const handleTagChange = (tag: string) => {
    if (activeTag === tag) return;
    setIsAnimating(true);
    setTimeout(() => {
        setActiveTag(tag);
        setVisibleCount(6);
        setTimeout(() => setIsAnimating(false), 50);
    }, 300);
  };

  return (
    <section id={SectionId.PORTFOLIO} className="py-24 pt-32 bg-slate-50 min-h-screen">
      <div className="container mx-auto px-6">
        <div className="text-center max-w-3xl mx-auto mb-12">
          <h2 className="text-sm font-bold text-brand-blue uppercase tracking-widest mb-3">Featured Work</h2>
          <h3 className="text-3xl md:text-4xl font-bold text-slate-900 leading-tight mb-4">
            Showcasing our success stories.
          </h3>
          <p className="text-slate-600 text-lg">
            From concept to launch, we've helped businesses across the globe achieve their digital goals.
          </p>
        </div>

        {/* Category Filters */}
        <div className="flex flex-wrap justify-center gap-3 mb-8">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => handleCategoryChange(cat)}
              className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 transform ${
                activeCategory === cat
                  ? 'bg-brand-blue text-white shadow-lg scale-105 ring-2 ring-brand-blue ring-offset-2 ring-offset-slate-50'
                  : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-100 hover:border-slate-300 hover:scale-105'
              }`}
            >
              {cat}
              <span className={`ml-2 text-xs font-bold ${activeCategory === cat ? 'text-slate-200' : 'text-slate-400'}`}>
                {getCategoryCount(cat)}
              </span>
            </button>
          ))}
        </div>

        {/* Tech Tag Filters */}
        <div className="flex items-center justify-center gap-2 mb-12 overflow-x-auto no-scrollbar py-2 px-4 max-w-5xl mx-auto">
          <div className="flex items-center gap-2 bg-white/50 p-2 rounded-full border border-slate-200 backdrop-blur-sm">
             <Tag size={16} className="text-slate-400 ml-2" />
             <div className="w-px h-4 bg-slate-300 mx-1"></div>
             {allTags.map((tag) => (
              <button
                key={tag}
                onClick={() => handleTagChange(tag)}
                className={`px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 whitespace-nowrap ${
                  activeTag === tag
                    ? 'bg-slate-800 text-white shadow-md'
                    : 'bg-transparent text-slate-500 hover:bg-slate-200 hover:text-slate-800'
                }`}
              >
                {tag}
                <span className={`ml-1.5 opacity-70 text-[10px]`}>
                   {getTagCount(tag)}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Projects Grid with Animation Wrapper */}
        <div className={`transition-opacity duration-300 ease-in-out ${isAnimating ? 'opacity-0 scale-[0.98]' : 'opacity-100 scale-100'}`}>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 min-h-[400px]">
            {displayedProjects.map((project) => (
                <ProjectCard 
                key={project.id} 
                project={project} 
                onClick={() => setSelectedProject(project)}
                />
            ))}

            {displayedProjects.length === 0 && (
                <div className="col-span-full flex flex-col items-center justify-center text-slate-400 py-12">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                    <Code2 className="w-8 h-8 text-slate-300" />
                </div>
                <p className="font-medium">No projects found for these filters.</p>
                <button 
                    onClick={() => { setActiveCategory(ALL_CATEGORY); setActiveTag(ALL_TAG); }}
                    className="mt-4 text-brand-blue text-sm hover:underline"
                >
                    Clear all filters
                </button>
                </div>
            )}
            </div>
        </div>

        {hasMore && !isAnimating && (
          <div className="mt-16 text-center">
            <Button 
              variant="outline"
              onClick={handleLoadMore}
              className="group px-8"
            >
              View More Projects
              <ArrowDown className="ml-2 w-4 h-4 transition-transform group-hover:translate-y-1" />
            </Button>
          </div>
        )}
      </div>

      {/* Modal Overlay */}
      <ProjectModal 
        project={selectedProject} 
        onClose={() => setSelectedProject(null)} 
        onProjectSelect={setSelectedProject}
      />
    </section>
  );
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  children, 
  ...props 
}) => {
  // Updated focus ring color to #642cdc (Brand Purple)
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-[#642cdc] focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none transform will-change-transform";

  const variants = {
    // Added hover opacity for transparency effect
    primary: "bg-brand-blue text-white hover:opacity-90 shadow-md hover:shadow-lg",
    secondary: "bg-slate-100 text-slate-900 hover:bg-slate-200/90",
    outline: "border border-slate-200 bg-transparent hover:bg-slate-50 text-slate-900",
    ghost: "hover:bg-slate-100/50 text-slate-700 hover:text-slate-900",
  };

  const sizes = {
    sm: "h-9 px-3 text-xs",
    md: "h-11 px-8 text-sm",
    lg: "h-14 px-8 text-base",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
