// --- Types & Constants ---
const ALL_CATEGORY = 'All';
const ALL_TAG = 'All Tech';

const formatTime = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return "0:00";
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
};

// --- Custom Video Player Component ---
interface CustomVideoPlayerProps {
  src: string;
  captionsUrl?: string;
  poster?: string;
}

const CustomVideoPlayer: React.FC<CustomVideoPlayerProps> = ({ src, captionsUrl, poster }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [captionsEnabled, setCaptionsEnabled] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const updateTime = () => setCurrentTime(video.currentTime);
    const updateDuration = () => setDuration(video.duration);
    const onEnded = () => setIsPlaying(false);

    video.addEventListener('timeupdate', updateTime);
    video.addEventListener('loadedmetadata', updateDuration);
    video.addEventListener('ended', onEnded);

    return () => {
      video.removeEventListener('timeupdate', updateTime);
      video.removeEventListener('loadedmetadata', updateDuration);
      video.removeEventListener('ended', onEnded);
    };
  }, []);

  useEffect(() => {
    const video = videoRef.current;
    if (video && video.textTracks && video.textTracks.length > 0) {
      video.textTracks[0].mode = captionsEnabled ? 'showing' : 'hidden';
    }
  }, [captionsEnabled]);

  const togglePlay = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseFloat(e.target.value);
    setVolume(newVol);
    if (videoRef.current) videoRef.current.volume = newVol;
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (videoRef.current) videoRef.current.currentTime = time;
  };

  return (
    <div className="relative w-full h-full bg-black group overflow-hidden flex flex-col justify-center">
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        className="w-full h-full object-contain"
        onClick={togglePlay}
        playsInline
        crossOrigin="anonymous"
      >
        {captionsUrl && <track kind="captions" src={captionsUrl} srcLang="en" label="English" default={false} />}
      </video>

      {/* Controls Overlay */}
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent p-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col gap-2 z-20">
        {/* Progress Bar */}
        <input
          type="range"
          min="0"
          max={duration || 0}
          value={currentTime}
          onChange={handleSeek}
          className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer accent-blue-500 hover:h-1.5 transition-all"
        />

        <div className="flex items-center justify-between text-white mt-1">
          <div className="flex items-center gap-4">
            <button onClick={togglePlay} className="hover:text-blue-400 transition-colors focus:outline-none">
              {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" />}
            </button>

            <div className="flex items-center gap-2 group/vol">
              {volume === 0 ? <VolumeX size={20} /> : <Volume2 size={20} />}
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={volume}
                onChange={handleVolumeChange}
                className="w-0 overflow-hidden group-hover/vol:w-20 transition-all duration-300 h-1 bg-slate-600 rounded-lg accent-white"
              />
            </div>

            <span className="text-xs font-mono opacity-80">
              {formatTime(currentTime)} / {formatTime(duration)}
            </span>
          </div>

          {captionsUrl && (
            <button
              onClick={() => setCaptionsEnabled(!captionsEnabled)}
              className={`transition-colors focus:outline-none ${captionsEnabled ? 'text-blue-400' : 'text-white/70 hover:text-white'}`}
              title="Toggle Captions"
            >
              <Subtitles size={20} />
            </button>
          )}
        </div>
      </div>

      {/* Big Play Button Overlay (when paused) */}
      {!isPlaying && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-16 h-16 bg-black/50 backdrop-blur-sm rounded-full flex items-center justify-center text-white/80 border border-white/20">
            <Play size={32} fill="currentColor" className="ml-1" />
          </div>
        </div>
      )}
    </div>
  );
};

// --- Modal Component ---
interface ProjectModalProps {
  project: Project | null;
  onClose: () => void;
}

const ProjectModal: React.FC<ProjectModalProps> = ({ project, onClose }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isClosing, setIsClosing] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (project) {
      setIsVisible(true);
      setIsClosing(false);
      document.body.style.overflow = 'hidden';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [project]);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
      setIsVisible(false);
      onClose();
      setIsClosing(false);
    }, 300);
  };

  if (!isVisible || !project) return null;

  const backdropClass = `fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[100] transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`;
  const modalContainerClass = `fixed inset-0 z-[101] flex items-center justify-center p-4 sm:p-6`;

  // Entrance: Zoom-in (scale-95 -> 100). Exit: Fade-out (opacity 0).
  const modalContentClass = `relative w-full max-w-5xl bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] transition-all duration-300 ease-out transform ${
    isClosing ? 'opacity-0 scale-95' : 'opacity-100 scale-100' // Using scale-100 for entrance final state
  }`;
  // For entrance animation, we rely on the mount transition. 
  // To make it zoom in from 0.95, we can use an animation class or simple CSS transition if rendered initially with scale-95.
  // Since it's conditional rendering, we might need a small timeout or CSS animation. 
  // Let's use a keyframe animation for entrance to be safe and `transition` for exit.

  return (
    <>
      <div className={backdropClass} onClick={handleClose} />
      <div className={modalContainerClass} onClick={(e) => e.target === e.currentTarget && handleClose()}>
        <div className={`${modalContentClass} animate-[zoomIn_0.3s_ease-out]`}>
          <button 
            onClick={handleClose}
            className="absolute top-4 right-4 p-2 bg-black/10 hover:bg-black/20 rounded-full z-50 transition-colors"
          >
            <X size={24} className="text-slate-900" />
          </button>

          <div ref={contentRef} className="overflow-y-auto custom-scrollbar">
            {/* Media Area */}
            <div className="w-full bg-black aspect-video relative">
              {project.demoVideoUrl ? (
                <CustomVideoPlayer 
                  src={project.demoVideoUrl} 
                  captionsUrl={project.captionsUrl} 
                  poster={project.imageUrl}
                />
              ) : (
                <img src={project.imageUrl} alt={project.title} className="w-full h-full object-cover" />
              )}
            </div>

            {/* Content Area */}
            <div className="p-8 md:p-10">
              <div className="flex flex-col md:flex-row gap-8 md:gap-12">
                <div className="flex-1 space-y-6">
                  <div>
                    <span className="inline-block px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold uppercase tracking-wider mb-3">
                      {project.category}
                    </span>
                    <h3 className="text-3xl md:text-4xl font-bold text-slate-900 mb-4">{project.title}</h3>
                    <p className="text-slate-600 text-lg leading-relaxed">
                      {project.fullDescription || project.description}
                    </p>
                  </div>

                  {project.technologies && (
                    <div>
                      <h4 className="font-bold text-slate-900 mb-3 flex items-center gap-2">
                        <Code2 size={18} className="text-blue-500" /> Technologies
                      </h4>
                      <div className="flex flex-wrap gap-2">
                        {project.technologies.map(tech => (
                          <span key={tech} className="px-3 py-1 bg-slate-100 text-slate-700 rounded-md text-sm font-medium">
                            {tech}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="w-full md:w-80 space-y-6">
                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-100">
                    <h4 className="font-bold text-slate-900 mb-4 text-sm uppercase tracking-wider">Project Details</h4>
                    <ul className="space-y-4 text-sm">
                      <li className="flex justify-between border-b border-slate-200 pb-3">
                        <span className="text-slate-500">Client</span>
                        <span className="font-medium">Confidential</span>
                      </li>
                      <li className="flex justify-between border-b border-slate-200 pb-3">
                        <span className="text-slate-500">Date</span>
                        <span className="font-medium flex items-center gap-1"><Calendar size={14}/> 2023</span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-slate-500">Category</span>
                        <span className="font-medium">{project.category}</span>
                      </li>
                    </ul>
                    {project.link && (
                      <Button className="w-full mt-6 gap-2" onClick={() => window.open(project.link, '_blank')}>
                        Visit Live Site <ExternalLink size={16} />
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes zoomIn {
