// --- Project Card Component ---
interface ProjectCardProps {
  project: Project;
  onClick: () => void;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onClick }) => {
  const [hovered, setHovered] = useState(false);
  const [shouldLoadVideo, setShouldLoadVideo] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);

  const handleMouseEnter = () => {
    setHovered(true);
    setShouldLoadVideo(true);
    // Attempt to play if video is loaded
    if (videoRef.current) {
      videoRef.current.play().catch(e => console.log("Autoplay prevented", e));
    }
  };

  const handleMouseLeave = () => {
    setHovered(false);
    if (videoRef.current) {
      videoRef.current.pause();
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsMuted(!isMuted);
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
    }
  };

  return (
    <div 
      className="group bg-white rounded-2xl overflow-hidden border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-500 ease-out cursor-pointer relative"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={onClick}
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-slate-100">
        {/* Base Image */}
        <img 
          src={project.imageUrl} 
          alt={project.title} 
          className={`w-full h-full object-cover transition-transform duration-700 group-hover:scale-105 ${hovered && project.demoVideoUrl ? 'opacity-0' : 'opacity-100'}`}
        />

        {/* Video Preview (Lazy Loaded) */}
        {project.demoVideoUrl && shouldLoadVideo && (
          <video
            ref={videoRef}
            src={project.demoVideoUrl}
            className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 ${hovered ? 'opacity-100' : 'opacity-0'}`}
            muted={isMuted}
            loop
            playsInline
          />
        )}

        {/* Overlays */}
        <div className="absolute inset-0 bg-slate-900/60 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center z-10 backdrop-blur-[1px]">
          <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 flex flex-col items-center gap-3">
            <button className="bg-white text-slate-900 px-6 py-2.5 rounded-full font-bold text-sm shadow-lg hover:bg-blue-50 flex items-center gap-2 transition-colors">
              View Case Study <ArrowUpRight size={16} />
            </button>
            {project.demoVideoUrl && (
               <span className="text-white/80 text-xs flex items-center gap-1">
                 <Film size={12} /> Video Preview
               </span>
            )}
          </div>
        </div>

        {/* Mute Toggle on Card */}
        {project.demoVideoUrl && hovered && (
          <button 
            onClick={toggleMute}
            className="absolute top-3 right-3 z-20 p-2 bg-black/50 hover:bg-black/70 rounded-full text-white backdrop-blur-sm transition-colors"
            title={isMuted ? "Unmute" : "Mute"}
          >
            {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
          </button>
        )}
      </div>

      <div className="p-6">
        <div className="flex justify-between items-start mb-2">
           <span className="text-xs font-bold text-blue-600 uppercase tracking-wider">{project.category}</span>
        </div>
        <h4 className="text-xl font-bold text-slate-900 mb-2 group-hover:text-blue-600 transition-colors">{project.title}</h4>
        <p className="text-slate-600 text-sm line-clamp-2">{project.description}</p>

        {project.technologies && (
            <div className="flex flex-wrap gap-1 mt-4">
                {project.technologies.slice(0, 3).map(tech => (
                    <span key={tech} className="text-[10px] px-2 py-1 bg-slate-100 text-slate-500 rounded-md">
                        {tech}
                    </span>
                ))}
                {project.technologies.length > 3 && (
                    <span className="text-[10px] px-2 py-1 bg-slate-100 text-slate-500 rounded-md">+{project.technologies.length - 3}</span>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

// --- Main Portfolio Component ---
export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(ALL_TAG);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  // Derived Data
  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const allTags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];

  // Counts
  const getCategoryCount = (cat: string) => cat === ALL_CATEGORY ? PROJECTS.length : PROJECTS.filter(p => p.category === cat).length;
  // Tag counts are global for simplicity, as per request "next to each ... technology tag"
  const getTagCount = (tag: string) => tag === ALL_TAG ? PROJECTS.length : PROJECTS.filter(p => p.technologies && p.technologies.includes(tag)).length;

  const filteredProjects = PROJECTS.filter(p => {
    const matchCat = activeCategory === ALL_CATEGORY || p.category === activeCategory;
    const matchTag = activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag));
