                {project.technologies.length > 3 && (
                    <span className="text-[10px] px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded">+{project.technologies.length - 3}</span>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

