    const statsObs = observeElement(statsRef, setIsStatsVisible, 0.5);
    const teamObs = observeElement(teamRef, setIsTeamVisible, 0.15);

    return () => {
      heroObs.disconnect();
      missionObs.disconnect();
      valuesObs.disconnect();
      statsObs.disconnect();
      teamObs.disconnect();
