        // Lower alpha for subtlety
        this.alpha = Math.random() * 0.2 + 0.1;
        this.targetAlpha = this.alpha;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;

        // Subtle Pulse effect
        if (Math.abs(this.alpha - this.targetAlpha) < 0.005) {
             this.targetAlpha = Math.random() * 0.2 + 0.1;
        } else {
             this.alpha += (this.targetAlpha - this.alpha) * 0.005;
        }

        // Wrap around screen
        if (canvas) {
           if (this.x > canvas.width) this.x = 0;
           if (this.x < 0) this.x = canvas.width;
           if (this.y > canvas.height) this.y = 0;
           if (this.y < 0) this.y = canvas.height;
        }
      }

      draw() {
        if (!ctx) return;
        ctx.fillStyle = `rgba(${this.color}, ${this.alpha})`;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    const init = () => {
      particles = [];
      // Optimal density
      const numberOfParticles = Math.floor(window.innerWidth / 15); 
      for (let i = 0; i < numberOfParticles; i++) {
        particles.push(new Particle());
      }
    };

    const animate = () => {
      if (!canvas || !ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (let i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].draw();
      }
      animationFrameId = requestAnimationFrame(animate);
    };

    window.addEventListener('resize', () => {
      resizeCanvas();
      init();
    });

    resizeCanvas();
    init();
    animate();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

